# 解题思路：使用二分法求解球体浸入水中的质量

import math

r = 10 / 100 # 球体半径（m）
rho = 0.638 # 球体密度（g/cm³）
g = 9.8 # 重力加速度（m/s²）
rho_w = 1 # 水的密度（g/cm³）

# 求解球体高度h部分的体积
def get_Vh(h):
    return math.pi / 3 * (3 * r * h ** 2 - h ** 3)

# 定义二分法求解函数
def bisection(func, a, b, max_iter=100, tol=1e-6):
    fa = func(a)
    fb = func(b)
    if fa * fb > 0:
        return None
    if fa == 0:
        return a
    if fb == 0:
        return b
    for i in range(1, max_iter + 1):
        mid = (a + b) / 2
        fmid = func(mid)
        if abs(fmid) < tol:
            return mid
        if fmid * fa > 0:
            a = mid
        else:
            b = mid
    return None

# 定义求解球体浸入水中质量的函数
def get_m():
    # 定义浮力与球重相等的方程
    def equation(m):
        V_w = m / rho_w
        s = rho / rho_w
        # 当 s < 0.5 时，球体高度为h部分的体积在水下
        if s < 0.5:
            h = r * (1 - math.sqrt(1 - 2 * s))
            V_h = get_Vh(h)
            return V_h + V_w - (4 / 3) * math.pi * r ** 3
        # 当 s > 0.5 时，球体高度为h部分的体积在水上
        else:
            h = r * (math.sqrt(1 + 2 * s) - 1)
            V_h = get_Vh(h)
            return V_w - V_h - (4 / 3) * math.pi * r ** 3
    # 使用二分法求解方程的根，得到球体浸入水中的质量
    return bisection(equation, 0, 10, tol=1e-6)

m = get_m()
print(f"球体浸入水中的质量为 {m:.6f} g")

